-- #371 (E1c): the rows of the matched Berlin-Hamburg comparison that
-- /berlin-vs-hamburg needs, read verbatim from the committed results table
-- docs/epic-e/matched-comparison-results.csv (generated by
-- analysis/thesis_hypothesis_suite.py --panel matched; metadata in
-- docs/epic-e/matched-comparison-metadata.json; results sign-offs
-- docs/epic-e/371-results-geo-signoff.md and 371-results-domain-signoff.md).
-- Same pattern as thesis_hypothesis_suite.sql: read straight from the CSV so the
-- page never hand-copies a number, and a regenerated CSV flows through on the next
-- `npm run sources`.
--
-- Not methodology-bearing here: a pass-through filter, no value altered or
-- re-derived.
-- * Rows kept:
-- - role 'primary' (T8 and N per city) and 'interaction' (X8, Delta = BER - HH);
-- - per-city N3 (role 'exploratory', untagged) and every BER-HH 'exploratory' row
-- (the N1-N3 city differences and the per-window H2/H3c rows);
-- - the sensitivity rows that set the A5.1 / §6.5 flags on those rows
-- (operationalisation tags ge5000, core2, core3m, W24, R19pub, fine), so the page
-- can render each flag's meaning ("sign unstable around zero", "unadjusted
-- significance change", "grain-dependent, MAUP") from the rows instead of a bare
-- token (domain sign-off R1, geo sign-off R2).
-- * `sens_tag` is the bracketed tag at the start of `operationalisation` ('' when
-- absent).
-- * `notes` is deliberately NOT selected: the binding page texts come from the
-- sign-offs, and the raw notes carry internal labels that must never reach the page.
-- * `holds` is not selected: this page reports the matched verdicts, not the
-- "Holds?" mapping (that lives on /thesis-recheck and /hamburg/thesis-recheck).
-- * `city` is kept as the city code (ADR-0005): 'BER', 'HH' or the pair 'BER-HH'.
with
    src as (
        select
            *,
            coalesce(
                regexp_extract(operationalisation, '^\[([^\]]+)\]', 1), ''
            ) as sens_tag
        from
            read_csv(
                '../docs/epic-e/matched-comparison-results.csv',
                header = true,
                all_varchar = true
            )
    )

select
    city,
    role,
    family,
    hypothesis,
    "window" as time_window,
    sens_tag,
    estimator,
    cast(estimate as double) as estimate,
    cast(ci_low as double) as ci_low,
    cast(ci_high as double) as ci_high,
    cast(p_boot as double) as p_boot,
    cast(p_bh as double) as p_bh,
    cast(mdd as double) as mdd,
    cast(n as integer) as n,
    cast(n_blocks as integer) as n_blocks,
    verdict,
    effect_label,
    flags,
    run_sha
from src
where
    role in ('primary', 'interaction')
    or (role = 'exploratory' and city = 'BER-HH')
    or (role = 'exploratory' and hypothesis = 'N3' and sens_tag = '')
    or sens_tag in ('ge5000', 'core2', 'core3m', 'W24', 'R19pub', 'fine')
